(function () {
  var N = 700;
  var ts = [], sig = [], am = [], fm = [], envT = [], envB = [];
  var fc = 22, dev = 12, fmF = 1.5;
  function msg(t) { return Math.sin(2 * Math.PI * fmF * t); }
  function env(t) { return 1 + 0.8 * msg(t); }
  function instFreq(t) { return fc + dev * msg(t); }
  // FM phase = 2π∫f dt ; ∫ sin(2π·1.5·t) dt = -cos(2π·1.5·t)/(2π·1.5)
  var kInt = dev / (2 * Math.PI * fmF);
  function fmPhase(t) { return 2 * Math.PI * fc * t - kInt * Math.cos(2 * Math.PI * fmF * t) + kInt; }

  for (var i = 0; i < N; i++) {
    var t = i / (N - 1);
    ts.push(t);
    var m = msg(t);
    sig.push({ x: t, y: 30 + 8 * m });
    var e = env(t);
    am.push({ x: t, y: 6 * e * Math.sin(2 * Math.PI * fc * t) });
    fm.push({ x: t, y: -30 + 6 * Math.sin(fmPhase(t)) });
    envT.push({ x: t, y: 6 * e });
    envB.push({ x: t, y: -6 * e });
  }

  var COL = { sig: '#111111', am: '#c0432c', fm: '#4a69bd' };
  function rgba(hex, a) {
    var r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
    return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
  }

  var curT = 0.2, decodeFM = false;

  function overlayData() {
    var arr = [];
    for (var i = 0; i < N; i++) {
      var t = ts[i], m = msg(t);
      arr.push({ x: t, y: decodeFM ? (-20 + 2.5 * m) : (16 + 3 * m) });
    }
    return arr;
  }

  var cursorPlugin = {
    id: 'cursor',
    afterDraw: function (chart) {
      var xs = chart.scales.x, area = chart.chartArea;
      if (!xs || !area) return;
      var px = xs.getPixelForValue(curT);
      var ctx = chart.ctx;
      ctx.save();
      ctx.strokeStyle = 'rgba(40,40,40,0.55)';
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 3]);
      ctx.beginPath();
      ctx.moveTo(px, area.top);
      ctx.lineTo(px, area.bottom);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = 'rgba(40,40,40,0.85)';
      ctx.beginPath();
      ctx.arc(px, area.top + 4, 3, 0, 2 * Math.PI);
      ctx.fill();
      ctx.restore();
    }
  };

