        tooltip: { enabled: false }
      },
      scales: {
        x: { type: 'linear', min: 0, max: 1, display: false },
        y: { type: 'linear', min: -42, max: 42, display: false }
      }
    },
    plugins: [cursorPlugin]
  });

  // right-end labels drawn on canvas via plugin
  var labelPlugin = {
    id: 'endlabels',
    afterDraw: function (c) {
      var area = c.chartArea, ctx = c.ctx, xs = c.scales.x, ys = c.scales.y;
      var px = xs.getPixelForValue(1) + 4;
      function lab(txt, wy, col) {
        ctx.save();
        ctx.font = '600 13px sans-serif';
        ctx.fillStyle = col;
        ctx.textBaseline = 'middle';
        ctx.fillText(txt, Math.min(px, c.width - 34), ys.getPixelForValue(wy));
        ctx.restore();
      }
      lab('Signal', 30, COL.sig);
      lab('AM', 0, COL.am);
      lab('FM', -30, COL.fm);
    }
  };
  chart.config.plugins = chart.config.plugins || [];
