  };

  window.toggle_decodeCarrier = function (on) {
    decodeFM = !!on;
    applyDecode();
  };

  // ---- demo step player ----
  var steps = [
    { title: 'The message to send',
      narration: 'The top black curve is the information (the "Signal"); the red and blue traces below are fast carriers that will hide this message inside them. Park the cursor on a crest and note the signal is high here.',
      state: { decodeCarrier: 'AM', timeScan: 0.2 } },
    { title: 'AM hides it in height',
      narration: 'Drag the cursor to the trough: the red AM wave\'s peak-to-trough height shrinks to its minimum exactly where the signal is lowest, and its dashed envelope redraws the signal shape — amplitude is doing the carrying.',
      state: { decodeCarrier: 'AM', timeScan: 0.5 } },
    { title: 'FM hides it in spacing',
      narration: 'Switch to FM and keep the cursor at the trough: the blue wave\'s height is unchanged, but its cycles are now stretched far apart — the message has moved into frequency (cycle spacing) instead of amplitude.',
      state: { decodeCarrier: 'FM', timeScan: 0.5 } },
    { title: 'Same message, two encodings',
      narration: 'Move the cursor to a crest under FM: cycles bunch tight and the reconstructed black signal above the blue trace matches the original. Decoding either carrier by reading its correct property recovers the very same signal.',
      state: { decodeCarrier: 'FM', timeScan: 0.8 } }
  ];
  var cur = 0;
  var narEl = document.getElementById('demoNarration');
  var labEl = document.getElementById('stepLabel');

  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    var chk = document.getElementById('decodeCarrierInput');
    chk.checked = (s.state.decodeCarrier === 'FM');
    window.toggle_decodeCarrier(chk.checked);
    var sl = document.getElementById('timeScanInput');
    sl.value = s.state.timeScan;
