    type: 'line',
    data: {
      datasets: [
        mkDS('Signal', sig, COL.sig, 2.4),
        mkDS('AM', am, COL.am, 1.6),
        mkDS('FM', fm, COL.fm, 1.6),
        mkDS('env+', envT, 'rgba(0,0,0,0)', 1.2, [5, 4]),
