        y: { type: 'linear', min: -42, max: 42, display: false }
      }
    },
    plugins: [cursorPlugin]
  });

  var labelPlugin = {
    id: 'endlabels',
    afterDraw: function (c) {
      var area = c.chartArea, ctx = c.ctx, xs = c.scales.x, ys = c.scales.y;
      var px = xs.getPixelForValue(1) + 8;
      function lab(txt, wy, col) {
