  function applyVisibility() {
    var ds = chart.data.datasets;
    if (!decodeActive) {
      ds[1].borderColor = COL.am;
      ds[2].borderColor = COL.fm;
      ds[3].borderColor = 'rgba(0,0,0,0)';
      ds[4].borderColor = 'rgba(0,0,0,0)';
      ds[5].borderColor = 'rgba(0,0,0,0)';
    } else {
      ds[1].borderColor = decodeFM ? rgba(COL.am, 0.30) : COL.am;
      ds[2].borderColor = decodeFM ? COL.fm : rgba(COL.fm, 0.30);
      if (decodeFM) {
        ds[3].borderColor = 'rgba(0,0,0,0)';
        ds[4].borderColor = 'rgba(0,0,0,0)';
      } else {
        ds[3].borderColor = rgba(COL.am, 0.55);
        ds[4].borderColor = rgba(COL.am, 0.55);
      }
      ds[5].borderColor = '#000000';
      ds[5].data = overlayData();
    }
    chart.update('none');
  }

  function updateReadout() {
    var m = msg(curT), e = env(curT), f = instFreq(curT);
    var el = document.getElementById('readoutBox');
    if (el) {
      el.innerHTML =
        '<b>t = ' + curT.toFixed(2) + '</b><br>' +
        'Signal height: <b>' + m.toFixed(2) + '</b><br>' +
        'AM envelope: <b>' + e.toFixed(2) + '</b><br>' +
        'FM inst. freq: <b>' + f.toFixed(1) + '</b> (spacing ' + (1 / f).toFixed(3) + ')';
    }
  }

  window.update_timeScan = function (v) {
    curT = v;
    updateReadout();
    chart.update('none');
  };

  window.toggle_decodeCarrier = function (on) {
    decodeFM = !!on;
    decodeActive = true;
    applyVisibility();
  };

  var steps = [
    { title: 'The message to send',
      narration: 'The top black curve is the information (the "Signal"); the red and blue traces below are fast carriers that will hide this message inside them. Park the cursor on a crest and note the signal is high here.',
      state: { decodeCarrier: false, timeScan: 0.2 } },
    { title: 'AM hides it in height',
      narration: 'Drag the cursor to the trough: the red AM wave\u2019s peak-to-trough height shrinks to its minimum exactly where the signal is lowest, and its dashed envelope redraws the signal shape \u2014 amplitude is doing the carrying.',
      state: { decodeCarrier: false, timeScan: 0.5 } },
    { title: 'FM hides it in spacing',
      narration: 'Switch to FM and keep the cursor at the trough: the blue wave\u2019s height is unchanged, but its cycles are now stretched far apart \u2014 the message has moved into frequency (cycle spacing) instead of amplitude.',
      state: { decodeCarrier: true, timeScan: 0.5 } },
    { title: 'Same message, two encodings',
      narration: 'Move the cursor to a crest under FM: cycles bunch tight and the reconstructed black signal above the blue trace matches the original. Decoding either carrier by reading its correct property recovers the very same signal.',
      state: { decodeCarrier: true, timeScan: 0.8 } }
  ];
  var cur = 0;
  var narEl = document.getElementById('demoNarration');
  var labEl = document.getElementById('stepLabel');

  function applyStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[cur];
    var chk = document.getElementById('decodeCarrierInput');
    chk.checked = !!s.state.decodeCarrier;
    decodeFM = !!s.state.decodeCarrier;
    decodeActive = (cur === 0) ? false : true;

    var sl = document.getElementById('timeScanInput');
    sl.value = s.state.timeScan;
    document.getElementById('timeScanVal').value = (+s.state.timeScan).toFixed(2);
    curT = s.state.timeScan;

    applyVisibility();
    updateReadout();
    chart.update('none');
    narEl.textContent = s.narration;
    labEl.textContent = (cur + 1) + '/' + steps.length + ' \u00b7 ' + s.title;
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyVisibility();
  updateReadout();
  applyStep(0);
  window.__markRendered();
})();
